function islandCount(floor: number[][]): number {
  const g = floor.map((r) => [...r]);
  let count = 0;
  for (let r = 0; r < g.length; r++) for (let c = 0; c < g[r].length; c++) {
    if (g[r][c] !== 1) continue;
    count++;
    const stack = [[r, c]];
    g[r][c] = 0;
    while (stack.length) {
      const [y, x] = stack.pop()!;
      for (const [dy, dx] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
        const ny = y + dy, nx = x + dx;
        if (g[ny]?.[nx] === 1) { g[ny][nx] = 0; stack.push([ny, nx]); }
      }
    }
  }
  return count;
}
